/* Minimal offline XLSX writer for Maghsalat Hameed */
window.XLSX=(function(){
function esc(s){return String(s??"").replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/>/g,"&gt;").replace(/"/g,"&quot;").replace(/'/g,"&apos;")}
function col(n){let s="";n++;while(n){let r=(n-1)%26;s=String.fromCharCode(65+r)+s;n=Math.floor((n-1)/26)}return s}
function aoa_to_sheet(a){return {data:a}}
function book_new(){return {sheets:[]}}
function book_append_sheet(wb,ws,name){wb.sheets.push({name,ws})}
function writeFile(wb,name){
  const data=wb.sheets[0].ws.data;
  let sheet=`<?xml version="1.0" encoding="UTF-8" standalone="yes"?><worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main"><sheetData>`;
  data.forEach((r,i)=>{sheet+=`<row r="${i+1}">`;r.forEach((v,j)=>{
    const addr=col(j)+(i+1), str=String(v??"");
    if(typeof v==="number" && isFinite(v)) sheet+=`<c r="${addr}"><v>${v}</v></c>`;
    else sheet+=`<c r="${addr}" t="inlineStr"><is><t xml:space="preserve">${esc(str)}</t></is></c>`;
  });sheet+="</row>"});
  sheet+="</sheetData></worksheet>";
  const files={
"[Content_Types].xml":`<?xml version="1.0" encoding="UTF-8"?><Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types"><Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/><Default Extension="xml" ContentType="application/xml"/><Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/><Override PartName="/xl/worksheets/sheet1.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/></Types>`,
"_rels/.rels":`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/></Relationships>`,
"xl/workbook.xml":`<?xml version="1.0" encoding="UTF-8"?><workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships"><sheets><sheet name="التقرير الأسبوعي" sheetId="1" r:id="rId1"/></sheets></workbook>`,
"xl/_rels/workbook.xml.rels":`<?xml version="1.0" encoding="UTF-8"?><Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships"><Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet1.xml"/></Relationships>`,
"xl/worksheets/sheet1.xml":sheet
  };
  zipStore(files).then(bytes=>{const a=document.createElement("a");a.href=URL.createObjectURL(new Blob([bytes],{type:"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet"}));a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),2000)})
}
async function zipStore(files){
  const enc=new TextEncoder(), parts=[], central=[]; let offset=0;
  function crc32(b){let c=0xFFFFFFFF;for(let x of b){c^=x;for(let k=0;k<8;k++)c=(c>>>1)^((c&1)?0xEDB88320:0)}return (c^0xFFFFFFFF)>>>0}
  const u32=n=>new Uint8Array([n&255,(n>>>8)&255,(n>>>16)&255,(n>>>24)&255]);
  const u16=n=>new Uint8Array([n&255,(n>>>8)&255]);
  for(const [name,text] of Object.entries(files)){
    const nb=enc.encode(name), b=enc.encode(text), crc=crc32(b);
    const h=new Uint8Array(30+nb.length);let v=new DataView(h.buffer);v.setUint32(0,0x04034b50,true);v.setUint16(4,20,true);v.setUint16(6,0,true);v.setUint16(8,0,true);v.setUint16(10,0,true);v.setUint16(12,0,true);v.setUint32(14,crc,true);v.setUint32(18,b.length,true);v.setUint32(22,b.length,true);v.setUint16(26,nb.length,true);v.setUint16(28,0,true);h.set(nb,30);
    parts.push(h,b);const c=new Uint8Array(46+nb.length);v=new DataView(c.buffer);v.setUint32(0,0x02014b50,true);v.setUint16(4,20,true);v.setUint16(6,20,true);v.setUint16(8,0,true);v.setUint16(10,0,true);v.setUint16(12,0,true);v.setUint16(14,0,true);v.setUint32(16,crc,true);v.setUint32(20,b.length,true);v.setUint32(24,b.length,true);v.setUint16(28,nb.length,true);v.setUint16(30,0,true);v.setUint16(32,0,true);v.setUint16(34,0,true);v.setUint16(36,0,true);v.setUint32(38,0,true);v.setUint32(42,offset,true);c.set(nb,46);central.push(c);offset+=h.length+b.length;
  }
  const cd=central.reduce((n,x)=>n+x.length,0), end=new Uint8Array(22);let v=new DataView(end.buffer);v.setUint32(0,0x06054b50,true);v.setUint16(8,central.length,true);v.setUint16(10,central.length,true);v.setUint32(12,cd,true);v.setUint32(16,offset,true);
  return new Blob([...parts,...central,end]).arrayBuffer().then(x=>new Uint8Array(x))
}
return {utils:{aoa_to_sheet},book_new,book_append_sheet,writeFile}
})();